\documentclass[11pt]{article}
\usepackage[margin=2.2cm]{geometry}
\usepackage{amsmath,amssymb}
\usepackage{booktabs}
\usepackage[hidelinks]{hyperref}
\usepackage{enumitem}
\setlength{\parskip}{0.5em}
\setlength{\parindent}{0pt}

\title{Assignment 3: Benchmarking Approximate Nearest Neighbour Search\\\large Full explanation}
\author{CS4.406 Information Retrieval \& Extraction}
\date{Due 25 October 2026, 23:59 IST}

\begin{document}
\maketitle

\section{Goal}
Measure the speed--accuracy trade-off of approximate nearest neighbour (ANN) indexes against exact search. Indexes: HNSW, IVF-Flat, IVF-PQ. Datasets: SIFT-1M and GloVe-100. One experiment chosen from a list (Part 3), one open-ended experiment on generated data (Part 4), and a report (Part 5). Grading values careful measurement and clear explanation, not which index is fastest.

\section{Problem}
Given vectors $x_1,\dots,x_N \in \mathbb{R}^d$ and a query $q$, the exact $k$-nearest-neighbour set is
\[
\mathrm{NN}_k(q) = \text{the } k \text{ indices minimising } \|q - x_i\|_2 .
\]
Exact search computes all $N$ distances per query, so its cost is $O(Nd)$ per query. Dense retrieval needs this step for every query. ANN indexes return an approximate set $\hat{\mathrm{NN}}_k(q)$ at lower cost, at the risk of missing true neighbours.

\section{Data}
\begin{itemize}[leftmargin=*]
  \item \textbf{SIFT}: 1{,}000{,}000 vectors, $d=128$, Euclidean distance. Ground truth in the file.
  \item \textbf{GloVe-100}: 1{,}183{,}514 word vectors, $d=100$, angular distance. Each vector is normalised to unit length, $\tilde{x} = x/\|x\|_2$, and Euclidean distance is used throughout. For unit vectors, $\|\tilde{q}-\tilde{x}\|^2 = 2 - 2\cos\theta$, so Euclidean and angular rankings agree.
  \item Each file has 10{,}000 queries and their true neighbours (ann-benchmarks format, HDF5 keys \texttt{train}, \texttt{test}, \texttt{neighbors}, \texttt{distances}).
  \item Query split: the first 5{,}000 queries are for tuning, the last 5{,}000 are for final reported numbers.
\end{itemize}

\section{Metric: recall@10 with ties}
For query $q$ with true $k$-th neighbour distance $r_k(q)$, a returned id $i$ is a hit if $\|q-x_i\|\le r_k(q)$. Recall for one query is
\[
R_k(q) = \frac{1}{k}\,\bigl|\{\, i \in \hat{\mathrm{NN}}_k(q) : \|q-x_i\| \le r_k(q)\,\}\bigr| ,
\]
and the reported recall is $\bar R_k = \frac{1}{|Q|}\sum_{q} R_k(q)$. Counting distance ties as hits means a result equally far as the true $k$-th neighbour is not penalised. Missing results (id $-1$) and duplicate ids are not hits. A tolerance of relative $10^{-5}$ absorbs float32 rounding. Distances are compared squared, which preserves order. Unit tests cover exact match, half match, ties, rounding tolerance, missing results, duplicates, averaging, and truncation to $k$.

\section{Part 1: exact baseline}
\begin{enumerate}[leftmargin=*]
  \item Build \texttt{IndexFlatL2} in FAISS. It computes $\|q-x_i\|^2$ for all $i$.
  \item Check: score the file's stored neighbours with the same recall function, using the exact $k$-th distance. Expected result: recall $1.0$ (ties allowed).
  \item Time exact search two ways:
  \begin{itemize}
    \item one query per call, one thread;
    \item all queries in one call, one thread and all threads.
  \end{itemize}
  \item Explain the gap. A single query streams all $N d$ floats from memory once for $2Nd$ flops, so it is memory-bandwidth-bound. A batch of $Q$ queries becomes a matrix product $QX^\top$, which reuses each loaded block of $X$ across many queries and is vectorised and parallel. Expected: batch throughput far above single-query throughput.
\end{enumerate}

\section{Part 2: the three indexes}
\subsection{HNSW (Hierarchical Navigable Small World)}
A multi-layer proximity graph. Each vector has up to $M$ links per layer ($2M$ at the base layer). Insertion uses a beam of width \texttt{efConstruction}. Search starts at the top layer and greedily moves to the closest neighbour until no move improves, then descends. At the base layer, a beam of width $\texttt{efSearch}$ is kept. Build settings: $M$, \texttt{efConstruction}. Search setting: \texttt{efSearch} ($\ge k$). Memory: raw vectors plus $\approx 2M$ integer links per vector.

\subsection{IVF-Flat (Inverted File, flat codes)}
Training: k-means with $\texttt{nlist}=L$ centroids $c_1,\dots,c_L$. Each vector is stored in the list of its nearest centroid. Search: find the \texttt{nprobe} nearest centroids to $q$, then compute exact distances to all vectors in those lists. Cost per query is about $\texttt{nprobe}\cdot N/L$ distance computations plus $L$ centroid comparisons. Memory: raw vectors plus one id per vector.

\subsection{IVF-PQ (Inverted File, product quantisation)}
Same coarse partition as IVF-Flat, but each vector is stored as a compressed code. Product quantisation splits the vector into $m$ sub-vectors of dimension $d/m$. Each sub-space gets a codebook of $2^{b}$ centroids (here $b=8$, so 256). A vector $x$ becomes $m$ one-byte codes. Asymmetric distance: for a query, precompute a table $T_j[c] = \|q_j - C_j[c]\|^2$ for each sub-space $j$ and code $c$; then
\[
\|q - \tilde{x}\|^2 \approx \sum_{j=1}^{m} T_j[\mathrm{code}_j(x)] .
\]
Memory per vector is $m$ bytes (plus the id). Quantisation error means the approximate distance is not the true distance, so the true neighbour can rank below other vectors. This sets a recall ceiling without re-ranking. Build settings: \texttt{nlist}, $m$. Search setting: \texttt{nprobe}.

\subsection{Build and search settings swept}
\begin{center}
\begin{tabular}{lll}
\toprule
Index & Build settings & Search sweep \\
\midrule
HNSW & $M\in\{8,16,32\}$, \texttt{efConstruction}$=200$ & \texttt{efSearch} $\in\{16,\dots,512\}$ \\
IVF-Flat & \texttt{nlist} $\in\{1024,4096\}$ & \texttt{nprobe} $\in\{1,\dots,256\}$ \\
IVF-PQ & \texttt{nlist} $\in\{1024,4096\}$, $m\in\{16,32\}$ (SIFT), $\{10,20\}$ (GloVe) & \texttt{nprobe} $\in\{1,\dots,256\}$ \\
\bottomrule
\end{tabular}
\end{center}

\subsection{Speed measurement}
Queries per second (QPS) is measured one query at a time, on one thread, as the median of three timings over the query half. Each query is a separate call, so the number includes per-call overhead in Python. The same overhead applies to all indexes.

\subsection{Operating points}
For each index and target recall $t\in\{0.90, 0.95\}$, the chosen setting is the fastest one (by tuning-half QPS) whose tuning-half recall is at least $t$. Its reporting-half recall and QPS are then reported. Plots show the Pareto frontier of reporting-half points: a point is kept only if no other point has both higher recall and higher QPS.

\subsection{Required outputs}
\begin{itemize}[leftmargin=*]
  \item One plot per dataset: recall@10 against QPS, with each index's best trade-off curve and the exact baseline.
  \item Table: QPS at recall 0.90 and 0.95.
  \item Table: build time, index size, bytes per vector at recall 0.95.
  \item One or two sentences on why any index fails to reach high recall, if one does.
\end{itemize}

\section{Part 3: one experiment on the standard data}
Choose one; write a hypothesis and commit it to git before running it.
\begin{description}[leftmargin=*]
  \item[Scaling.] SIFT at $N\in\{100\text{K},300\text{K},1\text{M}\}$. Measure the cost of reaching recall 0.95. Ground truth is recomputed for each $N$. Model: $\mathrm{QPS}\propto N^{s}$, and $s$ is fitted on a log--log scale. Expected: exact $s\approx -1$; HNSW $s$ small in magnitude; IVF-Flat with $\texttt{nlist}\propto\sqrt{N}$ near $s\approx -0.5$ if the required \texttt{nprobe} is constant.
  \item[Query difficulty.] GloVe-100. Measure relative contrast per query, group into four bins, and compare recall per bin.
  \item[Compression.] SIFT. Vary $m$; compare IVF-PQ with and without exact re-ranking of the top 100 candidates, in recall, speed, and memory.
\end{description}
This project runs \textbf{Scaling}. Hypothesis: \texttt{code/hypothesis.md}, Part 3 section.

\section{Part 4: one experiment on data we generate}
Ask a question about one trade-off or failure mode, different from Part 3. Study it in at least two of the three indexes. Data must be generated (from scratch or transformed). Requirements:
\begin{itemize}[leftmargin=*]
  \item Change one property at a time.
  \item At least three settings of that property, plus an unchanged control.
  \item Seeded generator, at most 500K vectors.
  \item Hypothesis committed before running.
  \item Report: one main figure and at most one page covering what changed, what happened, the mechanism, whether the hypothesis held, and what was not tested.
\end{itemize}
Ideas offered: drifting data, update cost, memory limits, hard geometry.

\subsection{Chosen experiment: dimension of uniform random vectors}
Generate $N=200{,}000$ vectors $x\sim\mathrm{Uniform}([0,1]^d)$ with seed $(20261020, d)$, and 1{,}000 queries from the same law with a separate seed stream. Settings $d\in\{16,64,256\}$, control $d=128$. Fixed build: HNSW $M=16$; IVF \texttt{nlist}$=1024$; PQ $m=16$. Fixed search grids as in Part 2 (smaller).

Mechanism measured directly: relative contrast of a query,
\[
